css:
#dlsub .k-prem{position:relative;display:inline-flex;align-items:center;gap:8px;margin-top:26px;height:34px;padding:0 14px;border-radius:999px;border:1px solid rgba(255,138,0,.55);background:rgba(255,138,0,.10);color:#ffb35c;font-size:13px;font-weight:700}
#dlsub .k-prem i{width:7px;height:7px;border-radius:50%;background:#ff8a00;box-shadow:0 0 10px #ff8a00}
#dlsub .k-ans{position:relative;margin-top:clamp(28px,3.4vw,48px);max-width:980px;padding:clamp(22px,2.4vw,32px) clamp(22px,2.6vw,36px);border-left:3px solid #ff8a00;border-radius:0 16px 16px 0;background:rgba(255,138,0,.07)}
#dlsub .k-ans b{display:block;font-family:Kanit,Pretendard,sans-serif;font-size:12px;font-weight:700;letter-spacing:.22em;color:#ff8a00}
#dlsub .k-ans p{margin:10px 0 0;font-size:clamp(15px,1.15vw,18px);line-height:1.9;color:#e9e4dc}
#dlsub .k-proof{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:clamp(32px,4vw,56px)}
#dlsub .k-proof figure{margin:0;border:1px solid #23262f;border-radius:18px;overflow:hidden;background:#0d0f15;transition:border-color .3s,transform .3s}
#dlsub .k-proof figure:hover{border-color:rgba(255,138,0,.5);transform:translateY(-3px)}
#dlsub .k-proof img{display:block;width:100%;height:auto;aspect-ratio:1600/1013;background:#0a0b0f}
#dlsub .k-proof figcaption{padding:18px 22px 22px}
#dlsub .k-proof figcaption span{display:inline-block;padding:4px 10px;border-radius:999px;border:1px solid #3a3d47;font-size:11.5px;font-weight:700;color:#ffc58a}
#dlsub .k-proof h3{margin:10px 0 0;font-size:clamp(16px,1.2vw,19px);line-height:1.45;font-weight:800;color:#fff}
#dlsub .k-proof p{margin:6px 0 0;font-size:14px;line-height:1.75;color:#9a9a9a}
#dlsub .k-note{margin-top:16px;font-size:12.5px;color:#7d8496}
#dlsub .k-cmp .k-card ul{list-style:none;margin:16px 0 0;padding:14px 0 0;border-top:1px solid #23262f;display:flex;flex-direction:column;gap:8px}
#dlsub .k-cmp .k-card li{display:flex;gap:8px;font-size:14px;line-height:1.6;color:#d6d0c6}
#dlsub .k-cmp .k-card li:before{content:"✓";color:#ff8a00;font-weight:800}
#dlsub .k-cmp .k-card .tgt{margin-top:12px;font-size:13px;color:#ffc58a}
#dlsub .k-chk{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:clamp(32px,4vw,56px);list-style:none;padding:0}
#dlsub .k-chk li{display:flex;gap:14px;align-items:flex-start;padding:20px 22px;border:1px solid #23262f;border-radius:16px;background:#0d0f15}
#dlsub .k-chk li b{flex:none;font-family:Kanit,Pretendard,sans-serif;font-size:14px;font-weight:700;color:#ff8a00;padding-top:2px}
#dlsub .k-chk strong{display:block;font-size:16px;line-height:1.45;color:#fff}
#dlsub .k-chk small{display:block;margin-top:4px;font-size:13px;line-height:1.6;color:#8a8a8a}
#dlsub .k-steps.s4{grid-template-columns:repeat(4,minmax(0,1fr))}
#dlsub .k-steps.s4 small{line-height:1.6}
#dlsub .k-pk{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:clamp(24px,4vw,64px);align-items:center;padding:clamp(28px,3.4vw,52px);border:1px solid #ff8a00;border-radius:22px;background:linear-gradient(180deg,rgba(255,138,0,.10),rgba(13,15,21,1) 70%)}
#dlsub .k-pk h3{margin:14px 0 0;font-size:clamp(22px,2.2vw,34px);line-height:1.35;font-weight:900;color:#fff}
#dlsub .k-pk p{margin:12px 0 0;font-size:14.5px;line-height:1.8;color:#b8b8b8}
#dlsub .k-pk ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 18px}
#dlsub .k-pk li{display:flex;gap:10px;font-size:14.5px;line-height:1.6;color:#e5e5e5}
#dlsub .k-pk li:before{content:"✦";color:#ff8a00}
@media(max-width:1099px){#dlsub .k-chk{grid-template-columns:repeat(2,minmax(0,1fr))}#dlsub .k-steps.s4{grid-template-columns:repeat(2,minmax(0,1fr))}#dlsub .k-pk{grid-template-columns:minmax(0,1fr)}}
@media(max-width:767px){#dlsub .k-proof,#dlsub .k-chk,#dlsub .k-pk ul{grid-template-columns:minmax(0,1fr)}#dlsub .k-proof figcaption{padding:16px 18px 18px}}
